[
  {
    "text": "JarvisHub treats an editable canvas as the user workspace, the agent's external memory, action space, and shared project state, representing multimodal artifacts, dependencies, versions, and feedback as typed canvas nodes and links.",
    "topic": "memory representation"
  },
  {
    "text": "Through a three-layer architecture of canvas state, protocol bridge, and agent runtime, JarvisHub enables agents to act within an inspectable and editable creative state.",
    "topic": "architecture"
  },
  {
    "text": "Existing prompt-based, chat-based, and node-based generation systems only partially support creative work state because they often discard intermediate context, rely on linear conversations, or require manually specified workflows.",
    "topic": "limitations of existing systems"
  },
  {
    "text": "Recent commercial systems indicate a shift toward agent-assisted creative production, but their closed architectures make it difficult to study how agents represent context, choose tools, revise artifacts, recover from failures, and maintain consistency over time.",
    "topic": "need for open systems"
  },
  {
    "text": "JarvisHub moves creative agents beyond isolated tool use toward sustained, human-steerable creative automation, where agents can progressively plan, generate, revise, and organize multimodal projects while users remain able to inspect, guide, and intervene throughout the process.",
    "topic": "creative automation"
  }
]
